import os
import anndata
import liana as li
import mudata as mu
import numpy as np
import pandas as pd
import scanpy as sc

if hasattr(anndata, "settings") and hasattr(anndata.settings, "allow_write_nullable_strings"):
    anndata.settings.allow_write_nullable_strings = True

def _get_transform_fn(name):
    if name == 'zi_minmax':
        return li.pp.zi_minmax
    elif name == 'neg_to_zero':
        return li.pp.neg_to_zero
    elif name == 'scale':
        return lambda x: sc.pp.scale(x, copy=True)
    return None

def _make_filter_fn(col, op, val_str):
    try:
        val = float(val_str)
    except ValueError:
        val = val_str
    ops = {
        'le': lambda s: s <= val,
        'lt': lambda s: s < val,
        'ge': lambda s: s >= val,
        'gt': lambda s: s > val,
        'eq': lambda s: s == val,
        'ne': lambda s: s != val,
    }
    return lambda row: bool(ops[op](row[col]))

if isinstance(adata, mu.MuData):
    adata.write_h5mu('output.h5mu')
else:
    adata.write_h5ad('anndata.h5ad', compression='gzip')
with open('anndata_info.txt', 'w', encoding='utf-8') as ainfo:
    print(adata, file=ainfo)
